<template>
  <section class="answer-layout-card" :class="{'section-layout':type==='sections', 'section-columns':columns}" :data-layout="type" :data-tone="tone">
    <header v-if="usefulTitle || card.intro" class="layout-heading"><h3 v-if="usefulTitle">{{usefulTitle}}</h3><MarkdownView v-if="card.intro" :content="text(card.intro)"/></header>
    <div v-if="type==='sections'" class="section-grid"><article v-for="(section,i) in sections" :key="i" class="answer-section"><MarkdownView v-if="section.heading" class="section-heading" :content="text(section.heading)"/><MarkdownView :content="text(section.body)"/></article></div>
    <div v-else-if="type==='faq'" class="faq-list"><details v-for="(item,i) in items" :key="i" :open="i===0"><summary><span>{{text(item.question)}}</span><span class="faq-symbol" aria-hidden="true">＋</span></summary><MarkdownView :content="text(item.answer)"/></details></div>
    <div v-else-if="type==='notice'" class="notice-body"><span class="notice-icon" aria-hidden="true">{{tone==='warning'?'!':tone==='success'?'✓':'i'}}</span><MarkdownView :content="text(card.body)"/></div>
    <div v-else class="layout-body"><MarkdownView :content="text(card.body)"/></div>
    <p v-if="card.note" class="layout-note">{{text(card.note)}}</p>
  </section>
</template>
<script setup lang="ts">
import {computed} from 'vue'
import MarkdownView from '../MarkdownView.vue'
const props=defineProps<{card:Record<string,unknown>}>()
const text=(v:unknown)=>typeof v==='string'?v:typeof v==='number'?String(v):''
const type=computed(()=>text(props.card.type))
const usefulTitle=computed(()=>{const title=text(props.card.title);return /^(答复要点|内容概览|内容说明|信息整理|要点整理|条目说明|信息对照)$/.test(title)?'':title})
const tone=computed(()=>['info','warning','success'].includes(text(props.card.tone))?text(props.card.tone):'info')
const objects=(v:unknown)=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'&&!Array.isArray(x)) as Record<string,unknown>[]:[]
const sections=computed(()=>objects(props.card.sections)),items=computed(()=>objects(props.card.items))
const columns=computed(()=>type.value==='sections'&&sections.value.length>=2&&sections.value.length<=6&&props.card.layout!=='flow'&&sections.value.every(s=>text(s.body).length<=360&&!text(s.body).includes('|')))
</script>
<style scoped>
.answer-layout-card{--card-accent:var(--nx-accent,var(--el-color-primary));border:1px solid var(--nx-border,var(--el-border-color));border-radius:14px;background:var(--nx-surface,var(--el-bg-color));color:var(--nx-text,var(--el-text-color-primary));overflow:hidden;min-width:0;max-width:100%}.layout-heading{padding:18px 20px 0}h3{margin:0 0 12px;font-size:16px;line-height:1.6;font-weight:650;overflow-wrap:anywhere}.section-grid{display:grid;gap:12px;grid-template-columns:minmax(0,1fr)}.section-layout{border:0;border-radius:0;background:transparent;overflow:visible}.section-layout>.layout-heading{padding:0}.section-columns .section-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.answer-section{padding:18px 20px;border:1px solid var(--nx-border,var(--el-border-color));border-radius:14px;background:var(--nx-surface,var(--el-bg-color));min-width:0}.section-heading{font-weight:650;color:var(--nx-text,var(--el-text-color-primary));margin-bottom:8px}.section-heading :deep(p){margin:0;font-size:15px!important}.answer-section :deep(.markdown-body){padding:0}.layout-body{padding:16px 20px;min-width:0;overflow-x:auto}.answer-layout-card[data-layout='reading']{border:0;background:transparent;border-radius:0}.answer-layout-card[data-layout='reading'] .layout-heading,.answer-layout-card[data-layout='reading'] .layout-body{padding-left:0;padding-right:0}.layout-note{margin:0;padding:12px 20px;font-size:12px;line-height:1.8;color:var(--nx-text-2,var(--el-text-color-secondary));overflow-wrap:anywhere}.faq-list details+details{border-top:1px solid var(--nx-border,var(--el-border-color))}.faq-list summary{padding:16px 20px;display:flex;justify-content:space-between;gap:16px;cursor:pointer;font-size:14px;font-weight:600;list-style:none;overflow-wrap:anywhere}.faq-list summary::-webkit-details-marker{display:none}.faq-symbol{color:var(--card-accent);flex-shrink:0}.faq-list details[open] .faq-symbol{transform:rotate(45deg)}.faq-list :deep(.markdown-body){padding:0 20px 16px}.answer-layout-card :deep(.markdown-body){font-size:14px;line-height:1.85;min-width:0;overflow-wrap:anywhere}.answer-section :deep(.markdown-body>p:first-child),.layout-body :deep(.markdown-body>p:first-child),.notice-body :deep(.markdown-body>p:first-child){margin-top:0}.answer-layout-card :deep(.markdown-body>p:last-child){margin-bottom:0}.notice-body{display:flex;gap:12px;align-items:flex-start;padding:16px 20px}.notice-body>.markdown-body{min-width:0;flex:1}.notice-icon{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;font-weight:700;font-size:12px;color:var(--card-accent);background:color-mix(in srgb,var(--card-accent) 12%,transparent);flex-shrink:0;margin-top:2px}.answer-layout-card[data-layout='notice']{border-left:3px solid var(--card-accent);background:color-mix(in srgb,var(--card-accent) 4%,var(--nx-surface,var(--el-bg-color)))}.answer-layout-card[data-tone='warning'][data-layout='notice']{--card-accent:var(--el-color-warning)}.answer-layout-card[data-tone='success'][data-layout='notice']{--card-accent:var(--el-color-success)}summary:focus-visible{outline:2px solid var(--card-accent);outline-offset:-3px}@media(max-width:600px){.section-columns .section-grid{grid-template-columns:minmax(0,1fr)}.layout-heading{padding:16px 16px 0}.answer-section,.layout-body,.layout-note,.notice-body{padding:16px}.faq-list summary{padding:16px}.faq-list :deep(.markdown-body){padding:0 16px 16px}}
</style>
